/**
 * HookExecutionEvent
 *
 * Event emitted when a hook is executed.
 *
 * This event provides observability into hook execution, including:
 * - Which hook type was triggered
 * - The command that was run
 * - The result (success/blocked/error)
 * - Any output from the hook
 *
 * This allows clients to track hook execution via the event stream.
 */
export type HookExecutionEvent = {
  /**
   * Id
   *
   * Unique event id (ULID/UUID)
   */
  id?: string;
  /**
   * Timestamp
   *
   * Event timestamp
   */
  timestamp?: string;
  /**
   * Source
   *
   * Source is always 'hook' for hook execution events
   */
  source?: 'agent' | 'user' | 'environment' | 'hook';
  /**
   * Parent Id
   *
   * Parent event id in the conversation tree. None for the root, or for legacy events predating the tree (see EventLog's effective-parent rule). Events sharing a parent_id are sibling branches.
   */
  parent_id?: string | null;
  /**
   * Hook Event Type
   *
   * The type of hook event that triggered this execution
   */
  hook_event_type:
    'PreToolUse' | 'PostToolUse' | 'UserPromptSubmit' | 'SessionStart' | 'SessionEnd' | 'Stop';
  /**
   * Hook Command
   *
   * The hook command that was executed
   */
  hook_command: string;
  /**
   * Tool Name
   *
   * Tool name for PreToolUse/PostToolUse hooks
   */
  tool_name?: string | null;
  /**
   * Success
   *
   * Whether the hook executed successfully
   */
  success: boolean;
  /**
   * Blocked
   *
   * Whether the hook blocked the operation (exit code 2 or deny)
   */
  blocked?: boolean;
  /**
   * Exit Code
   *
   * Exit code from the hook command
   */
  exit_code: number;
  /**
   * Stdout
   *
   * Standard output from the hook
   */
  stdout?: string;
  /**
   * Stderr
   *
   * Standard error from the hook
   */
  stderr?: string;
  /**
   * Reason
   *
   * Reason provided by hook (for blocking)
   */
  reason?: string | null;
  /**
   * Additional Context
   *
   * Additional context injected by hook (e.g., for UserPromptSubmit)
   */
  additional_context?: string | null;
  /**
   * Error
   *
   * Error message if hook execution failed
   */
  error?: string | null;
  /**
   * Action Id
   *
   * ID of the action this hook is associated with (PreToolUse/PostToolUse)
   */
  action_id?: string | null;
  /**
   * Message Id
   *
   * ID of the message this hook is associated with (UserPromptSubmit)
   */
  message_id?: string | null;
  /**
   * Hook Input
   *
   * The input data that was passed to the hook
   */
  hook_input?: {
    [key: string]: unknown;
  } | null;
  /**
   * Kind
   */
  kind: 'HookExecutionEvent';
};

