/**
 * TelemetrySpec
 *
 * Deployment-supplied product-analytics transport settings.
 *
 * This carries *transport* only. Whether telemetry may be delivered is
 * resolved from consent (``misc_settings.telemetry.consent``, optionally
 * seeded or overridden by ``OH_TELEMETRY_CONSENT``) — there is no deployment
 * "mode" here, and nothing in the agent-server special-cases a hosted
 * deployment.
 */
export type TelemetrySpec = {
  /**
   * Exporter
   *
   * Exporter to use. 'none' (the default) never delivers, and is what library and headless consumers get. 'posthog' requires the [posthog] extra. 'http' POSTs sanitized batches to telemetry_http_endpoint.
   */
  exporter?: 'none' | 'posthog' | 'http';
  /**
   * Posthog Api Key
   *
   * PostHog project API key. Required by the 'posthog' exporter; without it telemetry stays inactive.
   */
  posthog_api_key?: null;
  /**
   * Posthog Host
   *
   * PostHog ingestion host.
   */
  posthog_host?: string;
  /**
   * Http Endpoint
   *
   * Endpoint the 'http' exporter POSTs sanitized event batches to. Intended to front a backend that revalidates auth and consent before forwarding onward.
   */
  http_endpoint?: string | null;
  /**
   * Http Token
   *
   * Bearer token sent by the 'http' exporter, if required.
   */
  http_token?: null;
  /**
   * Salt
   *
   * Key used to pseudonymize conversation identifiers. Falls back to a per-process random salt, which keeps pseudonyms stable within a run but unlinkable across runs.
   */
  salt?: null;
  /**
   * Max Queue Size
   *
   * Upper bound on buffered diagnostic events. The queue is bounded on ingest: past this many events the oldest are dropped, so a failing exporter cannot grow memory without limit.
   */
  max_queue_size?: number;
  /**
   * Event Buffer Size
   *
   * Maximum events per delivery batch.
   */
  event_buffer_size?: number;
  /**
   * Flush Delay
   *
   * Seconds to wait before flushing a partial batch.
   */
  flush_delay?: number;
  /**
   * Num Retries
   *
   * Retries before a batch is dropped.
   */
  num_retries?: number;
  /**
   * Retry Delay
   *
   * Base seconds between delivery retries.
   */
  retry_delay?: number;
};

/**
 * TerminalAction
 *
 * Schema for terminal command execution.
 */
export type TerminalAction = {
  /**
   * Command
   *
   * The shell command to execute. Can be empty string to view additional logs when the previous exit code is `-1`. Can be a special key name when `is_input` is True: `C-c` (Ctrl+C), `C-d` (Ctrl+D/EOF), `C-z` (Ctrl+Z), or any `C-<letter>` for Ctrl sequences; navigation keys `UP`, `DOWN`, `LEFT`, `RIGHT`, `HOME`, `END`, `PGUP`, `PGDN`; and `TAB`, `ESC`, `BS` (Backspace), `ENTER`. You can only execute one command at a time. Use the platform-appropriate shell syntax described in the tool description when chaining commands.
   */
  command: string;
  /**
   * Is Input
   *
   * If True, the command is an input to the running process. If False, the command is executed in the terminal session. Default is False.
   */
  is_input?: boolean;
  /**
   * Timeout
   *
   * Optional. Sets a maximum time limit (in seconds) for running the command. If the command takes longer than this limit, you’ll be asked whether to continue or stop it. If you don’t set a value, the command will instead pause and ask for confirmation when it produces no new output for 30 seconds. Use a higher value if the command is expected to take a long time (like installation or testing), or if it has a known fixed duration (like sleep).
   */
  timeout?: number | null;
  /**
   * Reset
   *
   * If True, reset the terminal by creating a new session. Use this only when the terminal becomes unresponsive. Note that all previously set environment variables and session state will be lost after reset. Cannot be used with is_input=True.
   */
  reset?: boolean;
  /**
   * Kind
   */
  kind: 'TerminalAction';
};

