/**
 * WebhookSpec
 *
 * Spec to create a webhook. All webhook requests use POST method.
 */
export type WebhookSpec = {
  /**
   * Event Buffer Size
   *
   * The number of events to buffer locally before posting to the webhook
   */
  event_buffer_size?: number;
  /**
   * Base Url
   *
   * The base URL of the webhook service. Events will be sent to {base_url}/events and conversation info to {base_url}/conversations
   */
  base_url: string;
  /**
   * Headers
   */
  headers?: {
    [key: string]: string;
  };
  /**
   * Flush Delay
   *
   * The delay in seconds after which buffered events will be flushed to the webhook, even if the buffer is not full. Timer is reset on each new event.
   */
  flush_delay?: number;
  /**
   * Num Retries
   *
   * The number of times to retry if the post operation fails
   */
  num_retries?: number;
  /**
   * Retry Delay
   *
   * The delay between retries
   */
  retry_delay?: number;
  /**
   * Max Queue Size
   *
   * Upper bound on the number of events buffered for delivery. When the downstream is failing and events are re-queued for retry, the oldest events are dropped past this bound to prevent unbounded memory growth.
   */
  max_queue_size?: number;
};

