/**
 * Tool
 *
 * Defines a tool to be initialized for the agent.
 *
 * This is only used in agent-sdk for type schema for server use.
 */
export type OpenhandsSdkToolSpecTool = {
  /**
   * Name
   *
   * Name of the tool class, e.g., 'TerminalTool'. Import it from an `openhands.tools.<module>` subpackage.
   */
  name: string;
  /**
   * Params
   *
   * Parameters for the tool's .create() method, e.g., {'working_dir': '/app'}
   */
  params?: {
    [key: string]: unknown;
  };
};

/**
 * openhands.sdk.tool.tool.ToolAnnotations
 *
 * Annotations to provide hints about the tool's behavior.
 *
 * Based on Model Context Protocol (MCP) spec:
 * https://github.com/modelcontextprotocol/modelcontextprotocol/blob/caf3424488b10b4a7b1f8cb634244a450a1f4400/schema/2025-06-18/schema.ts#L838
 */
export type OpenhandsSdkToolToolToolAnnotations = {
  /**
   * Title
   *
   * A human-readable title for the tool.
   */
  title?: string | null;
  /**
   * Readonlyhint
   *
   * If true, the tool does not modify its environment. Default: false
   */
  readOnlyHint?: boolean;
  /**
   * Destructivehint
   *
   * If true, the tool may perform destructive updates to its environment. If false, the tool performs only additive updates. (This property is meaningful only when `readOnlyHint == false`) Default: true
   */
  destructiveHint?: boolean;
  /**
   * Idempotenthint
   *
   * If true, calling the tool repeatedly with the same arguments will have no additional effect on the its environment. (This property is meaningful only when `readOnlyHint == false`) Default: false
   */
  idempotentHint?: boolean;
  /**
   * Openworldhint
   *
   * If true, this tool may interact with an 'open world' of external entities. If false, the tool's domain of interaction is closed. For example, the world of a web search tool is open, whereas that of a memory tool is not. Default: true
   */
  openWorldHint?: boolean;
};

/**
 * ACPAgent
 *
 * Agent that delegates to an ACP-compatible subprocess server.
 */
export type AcpAgentInputWritable = {
  llm?: LlmInputWritable;
  /**
   * Tools
   */
  tools?: Array<ToolInput>;
  /**
   * Mcp Config
   *
   * Optional MCP servers to expose as tools.
   */
  mcp_config?: {
    [key: string]: McpServerInputWritable;
  };
  /**
   * Filter Tools Regex
   *
   * Optional regex to filter the tools available to the agent by name. This is applied after any tools provided in `tools` and any MCP tools are added.
   */
  filter_tools_regex?: string | null;
  /**
   * Include Default Tools
   */
  include_default_tools?: Array<string>;
  /**
   * Optional AgentContext to initialize the agent with specific context.
   */
  agent_context?: AgentContextInputWritable | null;
  /**
   * System Prompt
   *
   * Inline system prompt string.  When provided, the agent uses this text verbatim as the system message instead of rendering from `system_prompt_filename`.  Mutually exclusive with a non-default `system_prompt_filename`.
   *
   * **Warning**: This is not recommended unless you know what you are doing (e.g. customising agent behaviour for a completely different task).  Setting this will override OpenHands' built-in system instructions that govern default agent behaviour.
   */
  system_prompt?: string | null;
  /**
   * System Prompt Filename
   *
   * System prompt template filename. Can be either:
   * - A relative filename (e.g., 'system_prompt.j2') loaded from the agent's prompts directory
   * - An absolute path (e.g., '/path/to/custom_prompt.j2')
   */
  system_prompt_filename?: string;
  /**
   * Security Policy Filename
   *
   * Security policy filename. The default 'security_policy.j2' is a back-compat sentinel (the file was removed) that selects the built-in default policy from the prompt registry -- it is not loaded from disk. Any other value names a custom policy file whose contents are inserted verbatim (NOT rendered as a Jinja template). Can be either:
   * - A relative filename (e.g., 'custom_security_policy.md') loaded from the agent's prompts directory
   * - An absolute path (e.g., '/path/to/custom_security_policy.md')
   * - Empty string to disable security policy
   */
  security_policy_filename?: string;
  /**
   * System Prompt Kwargs
   *
   * Optional kwargs to pass to the system prompt Jinja2 template.
   */
  system_prompt_kwargs?: {
    [key: string]: unknown;
  };
  /**
   * Optional condenser to use for condensing conversation history.
   */
  condenser?: CondenserBaseInputWritable | null;
  /**
   * EXPERIMENTAL: Optional critic to evaluate agent actions and messages in real-time. API and behavior may change without notice. May impact performance, especially in 'all_actions' mode.
   */
  critic?: CriticBaseInputWritable | null;
  /**
   * Tool Concurrency Limit
   *
   * Maximum number of tool calls to execute concurrently within a single agent step. Default is 1 (sequential). Values > 1 enable parallel execution; concurrent tools share the conversation object, filesystem, and working directory, so mutations to shared state may race.
   */
  tool_concurrency_limit?: number;
  /**
   * Acp Command
   *
   * Command to start the ACP server, e.g. ['npx', '-y', '@agentclientprotocol/claude-agent-acp']
   */
  acp_command: Array<string>;
  /**
   * Acp Server
   *
   * Provider registry key identifying which ACP CLI this agent runs ('claude-code', 'codex', 'gemini-cli', or 'custom'); None when the agent is built directly rather than via ACPAgentSettings. Set by ACPAgentSettings.create_agent() from ACPAgentSettings.acp_server so the authoritative key survives onto the agent — and thus onto ConversationInfo.agent — because the launch command in acp_command does not reliably reverse-map to a provider. Informational only: consumers use it to resolve a provider brand label / model list; the subprocess is still launched from acp_command.
   */
  acp_server?: string | null;
  /**
   * Acp Args
   *
   * Additional arguments for the ACP server command
   */
  acp_args?: Array<string>;
  /**
   * Acp Session Mode
   *
   * Session mode ID to set after creating a session. If None (default), auto-detected from the ACP server type: 'bypassPermissions' for claude-agent-acp, 'agent-full-access' for codex-acp.
   */
  acp_session_mode?: string | null;
  /**
   * Acp Prompt Timeout
   *
   * Inactivity timeout in seconds for a single ACP prompt() call. The deadline resets on every update from the ACP server (token, thought, tool-call progress, usage), so a steadily-progressing agent runs as long as it keeps making progress; the prompt is only aborted after this many seconds with no activity at all. Prevents indefinite hangs when the ACP server stops responding without killing legitimately long-running work.
   */
  acp_prompt_timeout?: number;
  /**
   * Acp Startup Timeout
   *
   * Timeout in seconds for ACP server startup: spawning the subprocess, the initialize/authenticate handshake, and new_session()/load_session(). Unlike acp_prompt_timeout, this is a hard deadline rather than an idle deadline, since startup has no intermediate progress signal to reset it against. Prevents an indefinite hang when the ACP server blocks on authentication (e.g. an expired token) without ever raising.
   */
  acp_startup_timeout?: number;
  /**
   * Acp Model
   *
   * Model for the ACP server to use (e.g. 'sonnet' or 'gpt-5.5'). Applied via the protocol — set_config_option(model) for configOptions-based servers (codex, claude), else set_session_model. If None, the server picks its default.
   */
  acp_model?: string | null;
  /**
   * Acp Resume Session Id
   *
   * Optional explicit ACP session id to resume. When set, takes precedence over the id persisted in ``state.agent_state`` and is used to call ``session/load`` on the ACP server. Designed for environments where the per-conversation filesystem (and therefore ``base_state.json``) does not survive across restarts (e.g. cloud sandbox recycles), but the id has been mirrored into durable storage elsewhere. Falls back to a fresh session if the server cannot load the id. Treated as a secret on the wire — possession of the id is enough to resume the underlying ACP session, so default serialization redacts it; pass ``expose_secrets='plaintext'`` (trusted backend) or ``expose_secrets='encrypted'`` plus a cipher (frontend round-trip) when the value must cross a serialization boundary.
   */
  acp_resume_session_id?: string | null;
  /**
   * Acp File Secrets
   *
   * Reserved 'file-content' credential secrets to materialise to disk before launching the subprocess (e.g. Codex auth.json, Gemini Vertex SA JSON). The SDK owns the mechanism (write the file in the runtime pod, set the env var, seed-if-absent); these specs are the policy. Defaults to the built-in supported providers; a downstream application may override or extend this to support other ACP servers with different file-auth schemes.
   */
  acp_file_secrets?: Array<AcpFileSecretSpec>;
  /**
   * Acp Isolate Data Dir
   *
   * Give the ACP subprocess a per-conversation CLI data/config root instead of the shared user ``HOME``. When True and the provider is recognised, point its data-dir env var (``CODEX_HOME`` / ``CLAUDE_CONFIG_DIR`` / ``HOME``; see ``ACPProviderInfo.data_dir_env_var``) at ``<persistence_dir>/acp/<provider>`` — the same per-conversation tree materialised file-secrets use. Required for correctness when several of a user's conversations share one sandbox (``SandboxGroupingStrategy != NO_GROUPING``), where they would otherwise race on one set of CLI auth/config/cache/lock files (see #1019). Off by default: with one sandbox per conversation the shared HOME is already private, and relocating it would hide a pre-existing interactive login. Downstream policy decides when to enable it; the SDK owns where the root lives.
   */
  acp_isolate_data_dir?: boolean;
  /**
   * Kind
   */
  kind?: 'ACPAgent';
};

