/**
 * AgentContext
 *
 * Central structure for managing prompt extension.
 *
 * AgentContext unifies all the contextual inputs that shape how the system
 * extends and interprets user prompts. It combines both static environment
 * details and dynamic, user-activated extensions from skills.
 *
 * Specifically, it provides:
 * - **Repository context / Repo Skills**: Information about the active codebase,
 * branches, and repo-specific instructions contributed by repo skills.
 * - **Runtime context**: Current execution environment (hosts, working
 * directory, secrets, date, etc.).
 * - **Conversation instructions**: Optional task- or channel-specific rules
 * that constrain or guide the agent’s behavior across the session.
 * - **Knowledge Skills**: Extensible components that can be triggered by user input
 * to inject knowledge or domain-specific guidance.
 *
 * Together, these elements make AgentContext the primary container responsible
 * for assembling, formatting, and injecting all prompt-relevant context into
 * LLM interactions.
 */
export type AgentContextInputWritable = {
  /**
   * Skills
   *
   * List of available skills that can extend the user's input.
   */
  skills?: Array<SkillInputWritable>;
  /**
   * System Message Suffix
   *
   * Optional suffix to append to the system prompt.
   */
  system_message_suffix?: string | null;
  /**
   * User Message Suffix
   *
   * Optional suffix to append to the user's message.
   */
  user_message_suffix?: string | null;
  /**
   * Load User Skills
   *
   * Whether to automatically load user skills from ~/.openhands/skills/ and ~/.openhands/microagents/ (for backward compatibility).
   */
  load_user_skills?: boolean;
  /**
   * Load Public Skills
   *
   * Whether to automatically load skills from the public OpenHands skills repository at https://github.com/OpenHands/extensions. This allows you to get the latest skills without SDK updates.
   */
  load_public_skills?: boolean;
  /**
   * Marketplace Path
   *
   * Relative marketplace JSON path within the public skills repository. Set to None to load all public skills without marketplace filtering.
   */
  marketplace_path?: string | null;
  /**
   * Registered Marketplaces
   *
   * Marketplace registrations for plugin resolution. Registrations with auto_load=True or a list of plugin names are resolved by LocalConversation at startup.
   */
  registered_marketplaces?: Array<MarketplaceRegistration>;
  /**
   * Load Project Skills
   *
   * Whether to automatically load project skills from the conversation workspace (e.g. .openhands/skills/, AGENTS.md). Unlike load_user_skills / load_public_skills, this flag is not resolved by AgentContext itself (the workspace path is unknown at validation time); LocalConversation resolves it lazily on the first send_message() / run(), when the workspace is known. Also unlike load_user_skills / load_public_skills (which yield to explicit skills on a name conflict), resolved project skills are authoritative: a project skill overrides a same-named skill already present in `skills`.
   */
  load_project_skills?: boolean;
  /**
   * Load Memory
   *
   * Whether to load persistent agent memory (MEMORY.md indexes under ~/.openhands/memory/ and <workspace>/.openhands/memory/) into the system prompt. Like load_project_skills, this flag is not resolved by AgentContext itself (the workspace path is unknown at validation time); LocalConversation resolves it lazily on the first send_message() / run() and stores the result in memory_context.
   */
  load_memory?: boolean;
  /**
   * Memory Context
   *
   * Resolved memory-index text rendered into the <MEMORY_CONTEXT> prompt block. Populated via model_copy by LocalConversation when load_memory is set; excluded from serialization because it is re-resolved from disk each session and must not bloat persisted conversation state.
   */
  memory_context?: string | null;
  /**
   * Disabled Skills
   *
   * Names of skills to EXCLUDE from this context — a deny-list applied after every skill source is loaded (auto-loaded user/public, explicit, and lazily-loaded project skills). A listed name absent from the loaded set is a harmless no-op. [] (the default) keeps every skill. This is the single, drift-tolerant skill-selection mechanism (agent profiles set it from their own deny-list; #4017).
   */
  disabled_skills?: Array<string>;
  /**
   * Secrets
   *
   * Dictionary mapping secret keys to values or secret sources. Secrets are used for authentication and sensitive data handling. Values can be either strings or SecretSource instances (str | SecretSource).
   */
  secrets?: {
    [key: string]: string | SecretSourceInputWritable;
  } | null;
  /**
   * Current Datetime
   *
   * Current date and time information to provide to the agent. Can be a datetime object (which will be formatted as ISO 8601) or a pre-formatted string. When provided, this information is included in the system prompt to give the agent awareness of the current time context. Defaults to the current (timezone-aware) datetime.
   */
  current_datetime?: string | string | null;
};

/**
 * AgentDefinition
 *
 * Agent definition loaded from Markdown file.
 *
 * Agents are specialized configurations that can be triggered based on
 * user input patterns. They define custom system prompts and tool access.
 */
export type AgentDefinitionWritable = {
  /**
   * Name
   *
   * Agent name (from frontmatter or filename)
   */
  name: string;
  /**
   * Description
   *
   * Agent description
   */
  description?: string;
  /**
   * Model
   *
   * Model to use ('inherit' uses parent model)
   */
  model?: string;
  /**
   * Color
   *
   * Display color for the agent
   */
  color?: string | null;
  /**
   * Tools
   *
   * List of allowed tools for this agent
   */
  tools?: Array<string>;
  /**
   * Skills
   *
   * List of skill names for this agent. Resolved from project/user directories.
   */
  skills?: Array<string>;
  /**
   * System Prompt
   *
   * System prompt content
   */
  system_prompt?: string;
  /**
   * Source
   *
   * Source file path for this agent
   */
  source?: string | null;
  /**
   * Level
   *
   * Scope where the agent was discovered. Set during discovery; None when loaded directly from a file.
   */
  level?: 'project' | 'user' | 'builtin' | 'plugin' | 'programmatic' | null;
  /**
   * When To Use Examples
   *
   * Examples of when to use this agent (for triggering)
   */
  when_to_use_examples?: Array<string>;
  /**
   * Hook configuration for this agent
   */
  hooks?: HookConfigInput | null;
  /**
   * Permission Mode
   *
   * How the subagent handles permissions. None inherits the parent policy, 'always_confirm' requires confirmation for every action, 'never_confirm' skips all confirmations, 'confirm_risky' only confirms actions above a risk threshold.
   */
  permission_mode?: string | null;
  /**
   * Max Iteration Per Run
   *
   * Maximum iterations per run. It must be strictly positive, or None for default.
   */
  max_iteration_per_run?: number | null;
  /**
   * Max Budget Per Run
   *
   * Maximum accumulated cost (USD) per run for this sub-agent. Must be strictly positive, or None for no budget.
   */
  max_budget_per_run?: number | null;
  /**
   * Mcp Config
   *
   * MCP servers for this agent.
   */
  mcp_config?: {
    [key: string]: McpServerInputWritable;
  } | null;
  /**
   * Mcp Servers
   *
   * Deprecated compatibility alias for mcp_config. Use mcp_config for new clients.
   */
  mcp_servers?: {
    [key: string]: unknown;
  } | null;
  /**
   * Profile Store Dir
   *
   * Path to the directory where LLM profiles are stored. If None, the default profile store directory is used.
   */
  profile_store_dir?: string | null;
  /**
   * Context condenser for the sub-agent. None applies a default summarizing condenser; set a NoOpCondenser to disable condensation.
   */
  condenser?: CondenserBaseInputWritable | null;
  /**
   * Metadata
   *
   * Additional metadata from frontmatter
   */
  metadata?: {
    [key: string]: unknown;
  };
};

