/**
 * InitRequest
 *
 * Runtime configuration delivered at /api/init time.
 *
 * Each field is optional and overrides the equivalent field on the dormant
 * ``Config``. Fields not provided keep the value the server was constructed
 * with (typically from env vars at pod startup). The set of overridable
 * fields is intentionally narrow — it covers the values that today are
 * "env-var shaped" and must change per-user, not image-build-time
 * configuration (Python deps, plugin set, etc.) which stays bound to the
 * warm-pool flavor.
 */
export type InitRequestWritable = {
  /**
   * Session Api Keys
   *
   * Per-user session API keys. If provided, all subsequent /api* requests must authenticate with one of these keys via the X-Session-API-Key header.
   */
  session_api_keys?: Array<string> | null;
  /**
   * Secret Key
   *
   * Symmetric secret used to encrypt persisted secrets. If not provided, falls back to the first session_api_key (matching the default Config behavior).
   */
  secret_key?: string | null;
  /**
   * Conversations Path
   *
   * Directory where conversations are persisted. Override this to point at the mounted user workspace.
   */
  conversations_path?: string | null;
  /**
   * Bash Events Dir
   *
   * Directory where bash events are persisted. Typically located inside the mounted user workspace.
   */
  bash_events_dir?: string | null;
  /**
   * Webhooks
   *
   * Per-user webhooks (e.g. for streaming events back).
   */
  webhooks?: Array<WebhookSpec> | null;
  /**
   * Web Url
   *
   * External URL where this server is reachable, used for root-path calculation. Only honored when not already set in dormant config.
   */
  web_url?: string | null;
  /**
   * Allow Cors Origins
   *
   * CORS origins to add to the existing localhost allowlist.
   */
  allow_cors_origins?: Array<string> | null;
  /**
   * Max Concurrent Runs
   *
   * Override the conversation-step concurrency limit.
   */
  max_concurrent_runs?: number | null;
  /**
   * Env
   *
   * Process environment variables to set before conversation services start. Useful for credentials consumed by tools (e.g. GITHUB_TOKEN). These are applied with ``os.environ.update``; existing values are overwritten.
   */
  env?: {
    [key: string]: string;
  } | null;
  /**
   * Product-analytics policy for this pod. Without this, a warm-pool pod keeps whatever mode it booted with (normally 'disabled'), so a deployment that expects telemetry must supply it here.
   */
  telemetry?: TelemetrySpecWritable | null;
};

