/**
 * Skill
 *
 * A skill provides specialized knowledge or functionality.
 *
 * Skill behavior depends on format (is_agentskills_format) and trigger:
 *
 * AgentSkills format (SKILL.md files):
 * - Always listed in <available_skills> with name, description, location
 * - Agent reads full content on demand (progressive disclosure)
 * - If has triggers: content is ALSO auto-injected when triggered
 *
 * Legacy OpenHands format:
 * - With triggers: Listed in <available_skills>, content injected on trigger
 * - Without triggers (None): Full content in <REPO_CONTEXT>, always active
 *
 * This model supports both OpenHands-specific fields and AgentSkills standard
 * fields (https://agentskills.io/specification) for cross-platform compatibility.
 */
export type SkillInputWritable = {
  /**
   * Name
   */
  name: string;
  /**
   * Content
   */
  content: string;
  /**
   * Trigger
   *
   * Trigger determines when skill content is auto-injected. None = no auto-injection (for AgentSkills: agent reads on demand; for legacy: full content always in system prompt). KeywordTrigger = auto-inject when keywords appear in user messages. TaskTrigger = auto-inject for specific tasks, may require user input.
   */
  trigger?:
    | ({
        type: 'keyword';
      } & KeywordTrigger)
    | ({
        type: 'task';
      } & TaskTrigger)
    | ({
        type: 'path';
      } & PathTrigger)
    | null;
  /**
   * Source
   *
   * The source path or identifier of the skill. When it is None, it is treated as a programmatically defined skill.
   */
  source?: string | null;
  /**
   * Mcp Tools
   *
   * MCP servers for the skill (repo skills only).
   */
  mcp_tools?: {
    [key: string]: McpServerInputWritable;
  } | null;
  /**
   * Inputs
   *
   * Input metadata for the skill (task skills only)
   */
  inputs?: Array<InputMetadata>;
  /**
   * Is Agentskills Format
   *
   * Whether this skill was loaded from a SKILL.md file following the AgentSkills standard. AgentSkills-format skills use progressive disclosure: always listed in <available_skills> with name, description, and location. If the skill also has triggers, content is auto-injected when triggered AND agent can read file anytime.
   */
  is_agentskills_format?: boolean;
  /**
   * Version
   *
   * Skill version (AgentSkills standard field).
   */
  version?: string;
  /**
   * Description
   *
   * A brief description of what the skill does and when to use it. Descriptions exceeding MAX_DESCRIPTION_LENGTH are truncated with a notice pointing to the skill's source path.
   */
  description?: string | null;
  /**
   * License
   *
   * The license under which the skill is distributed. AgentSkills standard field (e.g., 'Apache-2.0', 'MIT').
   */
  license?: string | null;
  /**
   * Compatibility
   *
   * Environment requirements or compatibility notes for the skill. AgentSkills standard field (e.g., 'Requires git and docker').
   */
  compatibility?: string | null;
  /**
   * Metadata
   *
   * Arbitrary key-value metadata for the skill. AgentSkills standard field for extensibility.
   */
  metadata?: {
    [key: string]: string;
  } | null;
  /**
   * Allowed Tools
   *
   * List of pre-approved tools for this skill. AgentSkills standard field (parsed from space-delimited string).
   */
  allowed_tools?: Array<string> | null;
  /**
   * Disable Model Invocation
   *
   * Whether this skill can only be activated by trigger matching and should not be advertised to the model for direct invocation.
   */
  disable_model_invocation?: boolean;
  /**
   * Resource directories for the skill (scripts/, references/, assets/). AgentSkills standard field. Only populated for SKILL.md directory format.
   */
  resources?: SkillResources | null;
};

/**
 * StartConversationRequest
 *
 * Payload to create a new conversation.
 *
 * Supports any concrete :class:`AgentBase` implementation, including regular
 * OpenHands agents and ACP agents. Clients may provide either a concrete
 * ``agent`` payload or an ``agent_settings`` payload; when ``agent_settings``
 * is provided without ``agent``, the settings are validated with the
 * ``agent_kind`` discriminator and converted to the appropriate agent type.
 */
export type StartConversationRequestWritable = {
  /**
   * Working directory for agent operations and tool execution.
   */
  workspace: LocalWorkspaceInput;
  /**
   * Worktree
   *
   * If true and the workspace is already inside a git repository, create a dedicated git worktree for this conversation under `/tmp/conversation-worktrees/<conversation_id>/<project_name>`.
   */
  worktree?: boolean;
  /**
   * Conversation Id
   *
   * Optional conversation ID. If not provided, a random UUID will be generated.
   */
  conversation_id?: string | null;
  /**
   * Controls when the conversation will prompt the user before continuing. Defaults to never.
   */
  confirmation_policy?: ConfirmationPolicyBaseInput;
  /**
   * Optional security analyzer to evaluate action risks.
   */
  security_analyzer?: SecurityAnalyzerBaseInputWritable | null;
  /**
   * Initial message to pass to the LLM
   */
  initial_message?: SendMessageRequest | null;
  /**
   * Max Iterations
   *
   * If set, the max number of iterations the agent will run before stopping. This is useful to prevent infinite loops.
   */
  max_iterations?: number;
  /**
   * Stuck Detection
   *
   * If true, the conversation will use stuck detection to prevent infinite loops.
   */
  stuck_detection?: boolean;
  /**
   * Secrets
   *
   * Secrets available in the conversation
   */
  secrets?: {
    [key: string]: SecretSourceInputWritable;
  };
  /**
   * Secrets Encrypted
   *
   * If true, indicates that secret values in the agent configuration are cipher-encrypted and should be decrypted by the server before use. This enables secure round-tripping of settings through untrusted clients (e.g., frontend) that received encrypted values via the X-Expose-Secrets header. Flow: client calls GET /api/settings with X-Expose-Secrets: encrypted to receive cipher-encrypted secrets, then passes them in the agent config with secrets_encrypted=True so the server can decrypt them.
   */
  secrets_encrypted?: boolean;
  /**
   * Tool Module Qualnames
   *
   * Mapping of tool names to their module qualnames from the client's registry. These modules will be dynamically imported on the server to register the tools for this conversation.
   */
  tool_module_qualnames?: {
    [key: string]: string;
  };
  /**
   * Client Tools
   *
   * Tools defined by the client via JSON spec. These tools have no server-side executor — when the agent calls them, an ActionEvent is emitted over the WebSocket and the client handles execution. The SDK returns an acknowledgment observation immediately.
   */
  client_tools?: Array<ClientToolSpecInput>;
  /**
   * Deployment context applied after agent or Agent Profile resolution. The stored Agent Profile is not modified.
   */
  agent_launch_additions?: AgentLaunchAdditions | null;
  /**
   * Agent Definitions
   *
   * Agent definitions from the client's registry. These are registered on the server so that task tools can see user-registered subagents.
   */
  agent_definitions?: Array<AgentDefinitionWritable>;
  /**
   * Plugins
   *
   * List of plugins to load for this conversation. Plugins are loaded and their skills/MCP config are merged into the agent. Hooks are extracted and stored for runtime execution.
   */
  plugins?: Array<PluginSource> | null;
  /**
   * Optional hook configuration for this conversation. Hooks are shell scripts that run at key lifecycle events (PreToolUse, PostToolUse, UserPromptSubmit, Stop, etc.). If both hook_config and plugins are provided, they are merged with explicit hooks running before plugin hooks.
   */
  hook_config?: HookConfigInput | null;
  /**
   * Tags
   *
   * Key-value tags for the conversation. Keys must be lowercase alphanumeric. Values are arbitrary strings up to 256 characters.
   */
  tags?: {
    [key: string]: string;
  };
  /**
   * User Id
   *
   * Optional user ID supplied by the hosting deployment, used to correlate this conversation with the identity that deployment already established. When set it is passed to Laminar.set_trace_user_id() so traces can be queried by user, and — where a host has enabled product analytics — it is reused verbatim as the analytics correlation id so events attach to the existing person rather than creating a duplicate identity. It is never generated by the SDK, and is omitted entirely when unset.
   */
  user_id?: string | null;
  /**
   * Observability Metadata
   *
   * Trace-level metadata to attach to observability backends. Values must be scalars or homogeneous scalar lists supported by OpenTelemetry.
   */
  observability_metadata?: {
    [key: string]: TraceMetadataValue;
  };
  /**
   * Observability Tags
   *
   * Tags to attach to the conversation root observability span.
   */
  observability_tags?: Array<string>;
  /**
   * Observability Span Name
   *
   * Optional named child span to emit under the conversation root. Use stable, low-cardinality names because observability backends may use span names for grouping or signal routing.
   */
  observability_span_name?: string;
  /**
   * Autotitle
   *
   * If true, automatically generate a title for the conversation from the first user message. Precedence: title_llm_profile (if set and loads) → agent.llm → message truncation.
   */
  autotitle?: boolean;
  /**
   * Title Llm Profile
   *
   * Optional LLM profile name for title generation. If set, the LLM is loaded from LLMProfileStore (~/.openhands/profiles/) and used for LLM-based title generation. This enables using a fast/cheap model for titles regardless of the agent's main model. If not set (or profile loading fails), title generation falls back to the agent's LLM.
   */
  title_llm_profile?: string | null;
  /**
   * Agent Settings
   *
   * Optional agent settings payload. If `agent` is omitted, this is validated with the AgentSettingsBase `agent_kind` discriminator and used to construct the concrete agent.
   */
  agent_settings?: {
    [key: string]: unknown;
  } | null;
  /**
   * Agent Profile Id
   *
   * Optional agent profile ID. When set, the agent-server resolves the referenced profile server-side (stores + cipher are required) and builds the agent from it. Mutually exclusive with `agent` and `agent_settings`. The SDK validator enforces exclusivity only — resolution happens in conversation_service, not here.
   */
  agent_profile_id?: string | null;
  agent?: AgentBaseInputWritable;
};

